        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug arises from directly accessing the `num_rx_queues` member of the `net_device` structure, which is conditionally compiled based on the `CONFIG_SYSFS` configuration. When `CONFIG_SYSFS` is disabled, this member does not exist, leading to compilation errors when the code attempts to reference it.

        Commit message:
        netvsc: don't access netdev->num_rx_queues directly

This structure member is hidden behind CONFIG_SYSFS, and we
get a build error when that is disabled:

drivers/net/hyperv/netvsc_drv.c: In function 'netvsc_set_channels':
drivers/net/hyperv/netvsc_drv.c:754:49: error: 'struct net_device' has no member named 'num_rx_queues'; did you mean 'num_tx_queues'?
drivers/net/hyperv/netvsc_drv.c: In function 'netvsc_set_rxfh':
drivers/net/hyperv/netvsc_drv.c:1181:25: error: 'struct net_device' has no member named 'num_rx_queues'; did you mean 'num_tx_queues'?

As the value is only set once to the argument of alloc_netdev_mq(),
we can compare against that constant directly.

Fixes: ff4a44199012 ("netvsc: allow get/set of RSS indirection table")
Fixes: 2b01888d1b45 ("netvsc: allow more flexible setting of number of channels")
Signed-off-by: Arnd Bergmann <arnd@arndb.de>
Reviewed-by: Haiyang Zhang <haiyangz@microsoft.com>
Signed-off-by: Stephen Hemminger <sthemmin@microsoft.com>
Signed-off-by: David S. Miller <davem@davemloft.net>  

        Patch:

 static int netvsc_set_channels(struct net_device *net,
 			       struct ethtool_channels *channels)
 {
 	struct net_device_context *net_device_ctx = netdev_priv(net);
 	struct hv_device *dev = net_device_ctx->device_ctx;
 	struct netvsc_device *nvdev = rtnl_dereference(net_device_ctx->nvdev);
 	unsigned int count = channels->combined_count;
 	bool was_running;
 	int ret;

 	/* We do not support separate count for rx, tx, or other */
 	if (count == 0 ||
 	    channels->rx_count || channels->tx_count || channels->other_count)
 		return -EINVAL;

-	if (count > net->num_tx_queues || count > net->num_rx_queues)
+	if (count > net->num_tx_queues || count > VRSS_CHANNEL_MAX)
 		return -EINVAL;

 	if (!nvdev || nvdev->destroy)
 		return -ENODEV;

 	if (nvdev->nvsp_version < NVSP_PROTOCOL_VERSION_5)
 		return -EINVAL;

 	if (count > nvdev->max_chn)
 		return -EINVAL;

 	was_running = netif_running(net);
 	if (was_running) {
 		ret = netvsc_close(net);
 		if (ret)
 			return ret;
 	}

 	rndis_filter_device_remove(dev, nvdev);

 	ret = netvsc_set_queues(net, dev, count);
 	if (ret == 0)
 		nvdev->num_chn = count;
 	else
 		netvsc_set_queues(net, dev, nvdev->num_chn);

 	if (was_running)
 		ret = netvsc_open(net);

 	/* We may have missed link change notifications */
 	schedule_delayed_work(&net_device_ctx->dwork, 0);

 	return ret;
 }


 static int netvsc_set_rxfh(struct net_device *dev, const u32 *indir,
 			   const u8 *key, const u8 hfunc)
 {
 	struct net_device_context *ndc = netdev_priv(dev);
 	struct netvsc_device *ndev = rtnl_dereference(ndc->nvdev);
 	struct rndis_device *rndis_dev;
 	int i;

 	if (!ndev)
 		return -ENODEV;

 	if (hfunc != ETH_RSS_HASH_NO_CHANGE && hfunc != ETH_RSS_HASH_TOP)
 		return -EOPNOTSUPP;

 	rndis_dev = ndev->extension;
 	if (indir) {
 		for (i = 0; i < ITAB_NUM; i++)
-			if (indir[i] >= dev->num_rx_queues)
+			if (indir[i] >= VRSS_CHANNEL_MAX)
 				return -EINVAL;

 		for (i = 0; i < ITAB_NUM; i++)
 			rndis_dev->ind_table[i] = indir[i];
 	}

 	if (!key) {
 		if (!indir)
 			return 0;

 		key = rndis_dev->rss_key;
 	}

 	return rndis_filter_set_rss_param(rndis_dev, key, ndev->num_chn);
 }



